// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount == 10);

        uint256 potBefore = c.pot();
        uint256 bankBefore = address(c.bank()).balance;

        address player = address(0x1234);
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        uint256 bankAfter = address(c.bank()).balance;

        assertTrue(potAfter == 0 || (bankAfter == bankBefore + 1 && potAfter == 0) || (potAfter > 0 && bankAfter == bankBefore));
    }
}

